def predict_delta(terms, q):
    names,A=design(terms); beta=np.linalg.lstsq(A,y,rcond=None)[0]
    # build row for baseline settings, hardware = each observed row's hardware (average over cluster mix)
    def rowvec(settings):
        cols=[np.ones(n)]
        for t in terms:
            if isinstance(t,str):
                vals=sorted(set(X[t]))
                for v in vals[1:]:
                    if t in settings: cols.append(np.full(n, float(settings[t]==v)))
                    else: cols.append((X[t]==v).astype(float))
            else:
                a,b=t
                def d(k):
                    vals=sorted(set(X[k])); out=[]
                    for v in vals[1:]:
                        out.append(np.full(n,float(settings[k]==v)) if k in settings else (X[k]==v).astype(float))
                    return out
                for ca in d(a):
                    for cb in d(b): cols.append(ca*cb)
        return np.column_stack(cols)
    s_from=dict(q['baseline']); s_from[q['knob']]=q['from']
    s_to=dict(q['baseline']); s_to[q['knob']]=q['to']
    return (rowvec(s_to)@beta - rowvec(s_from)@beta).mean()
M1=base+[('lr_scale','warmup'),('micro_bs','zero_stage')]
