    if q['to'] not in set(X[q['knob']]) or q['from'] not in set(X[q['knob']]): print(q['id'],'level never observed'); continue
    d1=predict_delta(M1,q); d2=predict_delta(M2,q); d3=predict_delta(M3,q)
    print(q['id'],q['knob'],q['from'],'->',q['to'],f'M1={d1:+.5f} M2knobs={d2:+.5f} M3all={d3:+.5f}')
