print('M1 sigma',r.std(), 'p',A.shape[1])
for k in ['grad_norm_p95','throughput_toks_s','step_time_ms']:
    print('resid corr with',k, np.corrcoef(r,X[k])[0,1])
# residual by combos of hw
for h in hw:
    print(h,{v:round(r[X[h]==v].mean(),5) for v in sorted(set(X[h]))})
